                    dp[i][j] = dp[i - 1][j - 1]
                else:
                    dp[i][j] = min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1]) + 1

        return dp[m][n]

    def find_similar_words(word_core, word_cores):
        similar_words = []
        for core in word_cores:
            if edit_distance(word_core, core) == 1:
                similar_words.append(core)
        return sorted(similar_words)

    word_cores = set()
    for line in sys.stdin:
        if line.strip() == '***':
            break
        word_cores.update(get_word_cores(line))

    results = {}
    for core in word_cores:
        similar_words = find_similar_words(core, word_cores)
        if similar_words:
            results[core] = similar_words

    for core in sorted(results.keys()):
        print(f"{core}: {' '.join(results[core])}")

    if not results:
